head.b:skin:
/* -----------------------------------------------
Theme Name: Lab Rangkaian Listrik Cilik - by Pak Rwanda
Template Blogger Resmi untuk Media Edukasi Fisika Siswa SD
----------------------------------------------- */
.section, .widget { margin: 0; padding: 0; }
.Navbar, #navbar-iframe { display: none !important; height: 0 !important; visibility: hidden !important; }

:root {
  --primary: #0284c7;
  --primary-dark: #0369a1;
  --primary-light: #e0f2fe;
  --amber: #f59e0b;
  --amber-light: #fef3c7;
  --bg-main: #f8fafc;
  --bg-card: #ffffff;
  --text-heading: #0f172a;
  --text-body: #334155;
  --text-muted: #64748b;
  --border-light: #e2e8f0;
}

* {
  box-sizing: border-box;
  scroll-behavior: smooth;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  background-color: var(--bg-main);
  color: var(--text-body);
  margin: 0;
  padding: 0;
  min-height: 100vh;
}

h1, h2, h3, h4, .font-heading {
  font-family: 'Fredoka', cursive, sans-serif;
}

.glass-nav {
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid rgba(226, 232, 240, 0.8);
}

.sim-card-shadow {
  box-shadow: 0 20px 45px -10px rgba(2, 132, 199, 0.18), 0 8px 20px -6px rgba(15, 23, 42, 0.08);
}

.feature-card {
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 32px -8px rgba(2, 132, 199, 0.15);
  border-color: #7dd3fc;
}

/* Embedded iframe responsive ratio */
.sim-iframe-container {
  position: relative;
  width: 100%;
  height: 720px;
  max-height: 85vh;
  border-radius: 20px;
  overflow: hidden;
  background: #0f172a;
}

@media (max-width: 768px) {
  .sim-iframe-container {
    height: 600px;
    max-height: 80vh;
  }
}

/* Blogger Post Feed Styles */
.blog-post-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 24px;
  margin-bottom: 24px;
  transition: box-shadow 0.2s ease;
}
.blog-post-card:hover {
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.06);
}
.blog-post-card h2 a {
  color: #0f172a;
  text-decoration: none;
  font-family: 'Fredoka', sans-serif;
}
.blog-post-card h2 a:hover {
  color: #0284c7;
}

body.script:
//
  function toggleSimFullscreen() {
    const container = document.getElementById('sim-container');
    if (!container) return;
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) {
        container.requestFullscreen();
      } else if (container.webkitRequestFullscreen) {
        container.webkitRequestFullscreen();
      }
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }
  }
//
